BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP104-1-28','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考特殊境遇家庭扶助條例第6條（緊急生活扶助每人每次以補助三個月為原則），最後修正公布日：第6條 2006-05-17，本題考試日 2015-02-07 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050075'),('SP104-2-31','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考特殊境遇家庭扶助條例第4條（特殊境遇家庭之情形，包括配偶處一年以上之徒刑或受拘束人身自由之保安處分一年以上且在執行中），最後修正公布日：第4條 2011-12-07，本題考試日 2015-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050075'),('SP105-1-07','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考特殊境遇家庭扶助條例第4條（特殊境遇家庭之情形；三個月內生活發生重大變故者，其重大變故須非因個人責任、債務或自願性失業等事由），最後修正公布日：第4條 2011-12-07，本題考試日 2016-01-30 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050075'),('SP106-1-17','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考特殊境遇家庭扶助條例第2條（扶助項目為緊急生活扶助、子女生活津貼、子女教育補助、傷病醫療補助、兒童托育津貼、法律訴訟補助及創業貸款補助，不含家庭照顧者津貼），最後修正公布日：第2條 2009-01-23，本題考試日 2017-02-18 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050075'),('SP107-1-34','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考特殊境遇家庭扶助條例第6條（緊急生活扶助按最低生活費用標準一倍核發、每人每次以補助三個月為原則、同一事由補助一次，應於事實發生後六個月內申請），最後修正公布日：第6條 2006-05-17，本題考試日 2018-02-03 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050075'),('SP107-2-08','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考特殊境遇家庭扶助條例第4條（特殊境遇家庭之情形），最後修正公布日：第4條 2011-12-07，本題考試日 2018-07-28 之後未再修正，考試時條文與現行條文相同，第4條第1項第1款規定為「六十五歲以下，其配偶死亡，或失蹤經向警察機關報案協尋未獲達六個月以上」，選項(D)「六十五歲以上」與條文不符，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050075'),('SP108-1-29','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考特殊境遇家庭扶助條例第8條（子女教育補助：就讀高中高職、大專院校減免學雜費百分之六十），最後修正公布日：第8條 2013-01-02，本題考試日 2019-01-19 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050075'),('SP108-2-34','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考特殊境遇家庭扶助條例第6條（緊急生活扶助應於事實發生後六個月內申請），最後修正公布日：第6條 2006-05-17，本題考試日 2019-07-27 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050075'),('SP109-2-35','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考特殊境遇家庭扶助條例第6條（緊急生活扶助按最低生活費用標準一倍核發，每人每次以補助三個月為原則），最後修正公布日：第6條 2006-05-17，本題考試日 2020-08-01 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050075'),('SP110-2-34','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考特殊境遇家庭扶助條例第4條（家庭總收入每人每月未超過最低生活費二點五倍及臺灣地區平均每人每月消費支出一點五倍），最後修正公布日：第4條 2011-12-07，本題考試日 2021-08-21 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050075'),('SP111-2-35','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考特殊境遇家庭扶助條例第13條之1（請領各項津貼或補助之權利不得扣押、讓與或供擔保），最後修正公布日：第13條之1 2014-01-29，本題考試日 2022-07-30 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050075'),('SP112-1-35','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考特殊境遇家庭扶助條例歷次修正內容。第9條傷病醫療補助之自行負擔醫療費用門檻仍為「超過新臺幣三萬元」，選項(A)所稱上調為五萬元與條文不符；第3條主管機關修正為衛生福利部、第13條之1專戶存款不得作為扣押、抵銷、供擔保或強制執行之標的、第12條創業貸款補助申請資格由年滿二十歲改為成年，均為考試前之修正。最後修正公布日：第3條 2020-01-15、第9條 2011-12-07、第12條 2021-01-20、第13條之1 2014-01-29，本題考試日 2023-02-18 之後本條例未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050075');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>12 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>12 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz)<>'150bb4e69f3685cc3bc0b2783131b676' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_12, count(*) FILTER (WHERE q.legal_status='changed') changed_0, count(*) total_12 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
